// Agent Workflow plugin for MiMo Code (generated by agent-workflow sync; do not edit).
// Adds the project-gated reminder to the system prompt. Before each shell call, cancels a
// test/build command whose exit status a pipe, ';' or echo would hide (AW_VALIDATION_COMPOUND).
// No commands, network, project code or transcript access; opted-out projects get nothing.
import {resolve} from 'node:path';
import {hookResult,shellGuard} from '__AW_GATE_URL__';

// MiMo's shell tool is bash; exec_command is its Codex-style alias (cmd instead of command).
const SHELL_TOOLS=['bash','exec_command'];

export const AgentWorkflow=async({directory}={})=>({
  'experimental.chat.system.transform':async(_input,output)=>{
    let text;
    try{text=hookResult({cwd:directory??process.cwd(),hook_event_name:'SessionStart'}).hookSpecificOutput?.additionalContext;}catch{return;}
    if(text&&Array.isArray(output?.system)&&!output.system.includes(text))output.system.push(text);
  },
  'tool.execute.before':async(input,output)=>{
    if(!SHELL_TOOLS.includes(input?.tool))return;
    const args=output?.args;if(!args||typeof args!=='object')return;
    const base=directory??process.cwd();
    let reason;
    try{reason=shellGuard(args.command??args.cmd,typeof args.workdir==='string'&&args.workdir?resolve(base,args.workdir):base);}catch{return;}
    if(reason){output.cancel=true;output.cancelReason=reason;}
  },
});
